#!/usr/bin/env python3
"""Fill placeholders in an HWPX template.

This script:
- Loads /root/project_proposal.json
- Extracts /root/project_proposal_template.hwpx (a zip)
- Replaces {{...}} placeholders inside paragraph text even if split across <hp:t>
- Normalizes budget formatting (remove commas after currency sign)
- Appends month-span "(N개월)" to 단계 일정 lines
- Removes layout cache elements (lineSeg/lineseg*) only for modified paragraphs
- Re-zips to /root/project_proposal_ready.hwpx preserving zip entry metadata
"""

from __future__ import annotations

import json
import os
import re
import tempfile
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET


TEMPLATE_PATH = "/root/project_proposal_template.hwpx"
JSON_PATH = "/root/project_proposal.json"
OUTPUT_PATH = "/root/project_proposal_ready.hwpx"

PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")


def load_json(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def collect_namespaces(xml_path: Path) -> dict[str, str]:
    """Collect namespaces found in an XML file."""
    ns: dict[str, str] = {}
    # iterparse emits ('start-ns', (prefix, uri))
    for event, data in ET.iterparse(str(xml_path), events=("start-ns",)):
        prefix, uri = data
        # Keep first occurrence of a prefix
        if prefix not in ns:
            ns[prefix] = uri
    return ns


def register_namespaces(ns: dict[str, str]) -> None:
    for prefix, uri in ns.items():
        # ElementTree uses '' for default namespace
        ET.register_namespace(prefix if prefix is not None else "", uri)


def local_name(tag: str) -> str:
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def is_layout_cache_tag(tag: str) -> bool:
    ln = local_name(tag).lower()
    # HWPX often caches layout under lineSeg/lineseg* elements.
    return "lineseg" in ln


def remove_layout_cache_elements(elem: ET.Element) -> int:
    """Remove any lineSeg/lineseg* descendants under elem. Returns count removed."""
    removed = 0
    for child in list(elem):
        if is_layout_cache_tag(child.tag):
            elem.remove(child)
            removed += 1
        else:
            removed += remove_layout_cache_elements(child)
    return removed


def normalize_budget(value: str) -> str:
    # Remove commas from the numeric portion but keep the leading currency symbol.
    if not isinstance(value, str):
        value = str(value)

    if value.startswith("₩"):
        return "₩" + value[1:].replace(",", "")
    return value.replace(",", "")


DATE_RANGE_RE = re.compile(
    r"(?P<sy>\d{4})[.\-](?P<sm>\d{1,2})"  # start
    r"(?:\s*~\s*(?P<ey>\d{4})[.\-](?P<em>\d{1,2}))?"  # optional end
)


def compute_month_span(text: str) -> int | None:
    """Compute month span from the first YYYY-MM (~ YYYY-MM) found in text.

    - If only one YYYY-MM is found (no ~ range), returns 1.
    - If range exists, returns inclusive month count.
    """
    m = DATE_RANGE_RE.search(text)
    if not m:
        return None

    sy = int(m.group("sy"))
    sm = int(m.group("sm"))
    ey = m.group("ey")
    em = m.group("em")

    if not ey or not em:
        return 1

    ey_i = int(ey)
    em_i = int(em)
    return (ey_i - sy) * 12 + (em_i - sm) + 1


def should_append_months(text: str) -> bool:
    # The template uses '1단계/2단계/3단계' labels.
    return bool(re.search(r"(^|\s)[123]단계\s*:", text))


def append_months_if_needed(text: str) -> str:
    if "개월" in text:
        return text
    if not should_append_months(text):
        return text

    span = compute_month_span(text)
    if span is None:
        return text

    return f"{text} ({span}개월)"


def replace_placeholders_in_paragraph(
    p: ET.Element,
    ns: dict[str, str],
    data: dict,
) -> tuple[bool, str, str]:
    """Replace placeholders in a single <hp:p> element.

    Returns (modified, old_text, new_text).
    """
    # Collect all hp:t elements (text runs) under this paragraph.
    if "hp" not in ns:
        # If a file doesn't use hp prefix, we can't reliably target <hp:t>.
        # Fall back to any element whose local-name is 't'.
        t_elems = [e for e in p.iter() if local_name(e.tag) == "t"]
    else:
        t_elems = p.findall(".//hp:t", ns)

    if not t_elems:
        return (False, "", "")

    old_text = "".join([(e.text or "") for e in t_elems])

    if "{{" not in old_text:
        # Still may need month span, but only if text already includes schedule.
        new_text = append_months_if_needed(old_text)
        if new_text != old_text:
            t_elems[0].text = new_text
            for e in t_elems[1:]:
                e.text = ""
            return (True, old_text, new_text)
        return (False, old_text, old_text)

    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in data:
            raise KeyError(f"Missing placeholder key in JSON: {key}")
        val = data[key]
        if key == "예산":
            return normalize_budget(str(val))
        return str(val)

    replaced = PLACEHOLDER_RE.sub(repl, old_text)
    replaced = append_months_if_needed(replaced)

    if replaced == old_text:
        return (False, old_text, replaced)

    # Put the entire replaced text into the first <hp:t>, clear the rest.
    t_elems[0].text = replaced
    for e in t_elems[1:]:
        e.text = ""

    return (True, old_text, replaced)


def process_xml_file(xml_path: Path, data: dict) -> bool:
    """Process a single XML file; returns True if any changes were made."""
    ns = collect_namespaces(xml_path)
    register_namespaces(ns)

    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    modified_any = False

    # Find paragraphs. Prefer hp:p when hp namespace is present; otherwise local-name fallback.
    if "hp" in ns:
        paragraphs = root.findall(".//hp:p", ns)
    else:
        paragraphs = [e for e in root.iter() if local_name(e.tag) == "p"]

    for p in paragraphs:
        modified, _old, _new = replace_placeholders_in_paragraph(p, ns, data)
        if modified:
            modified_any = True
            # Remove layout cache elements only for paragraphs we touched.
            remove_layout_cache_elements(p)

    if modified_any:
        tree.write(str(xml_path), encoding="utf-8", xml_declaration=True)

    return modified_any


def verify_no_placeholders(root_dir: Path) -> None:
    bad: list[str] = []
    for xml_path in root_dir.rglob("*.xml"):
        try:
            txt = xml_path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            # HWPX xml should be utf-8, but be defensive.
            txt = xml_path.read_text(encoding="utf-8", errors="replace")
        if "{{" in txt:
            bad.append(str(xml_path))

    if bad:
        raise RuntimeError("Placeholders remain in: " + ", ".join(bad))


def rezip_preserving_structure(src_zip: str, extracted_dir: Path, out_zip: str) -> None:
    with zipfile.ZipFile(src_zip, "r") as zin:
        infos = zin.infolist()

        with zipfile.ZipFile(out_zip, "w") as zout:
            for info in infos:
                name = info.filename

                # Directory entry
                if name.endswith("/"):
                    # Preserve directory entries if present
                    zi = zipfile.ZipInfo(filename=name, date_time=info.date_time)
                    zi.compress_type = info.compress_type
                    zi.external_attr = info.external_attr
                    zi.comment = info.comment
                    zi.extra = info.extra
                    zi.create_system = info.create_system
                    zi.flag_bits = info.flag_bits
                    zout.writestr(zi, b"")
                    continue

                disk_path = extracted_dir / name
                if disk_path.exists():
                    data = disk_path.read_bytes()
                else:
                    data = zin.read(name)

                zi = zipfile.ZipInfo(filename=name, date_time=info.date_time)
                zi.compress_type = info.compress_type
                zi.external_attr = info.external_attr
                zi.comment = info.comment
                zi.extra = info.extra
                zi.create_system = info.create_system
                zi.flag_bits = info.flag_bits

                zout.writestr(zi, data)


def main() -> None:
    data = load_json(JSON_PATH)

    with tempfile.TemporaryDirectory(prefix="hwpx_work_") as td:
        work = Path(td)
        with zipfile.ZipFile(TEMPLATE_PATH, "r") as z:
            z.extractall(work)

        # Process all XML files under the extracted tree.
        changed_files = 0
        for xml_path in sorted(work.rglob("*.xml")):
            if process_xml_file(xml_path, data):
                changed_files += 1

        verify_no_placeholders(work)

        # Build the output HWPX while preserving the original zip entry ordering & metadata.
        rezip_preserving_structure(TEMPLATE_PATH, work, OUTPUT_PATH)

    print(f"Wrote: {OUTPUT_PATH}")


if __name__ == "__main__":
    main()

